create table public.suppliers(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,legal_name text not null check(length(trim(legal_name)) between 2 and 240),trade_name text,document_number text,category text not null check(length(trim(category)) between 2 and 100),status text not null default 'ACTIVE' check(status in('ACTIVE','SUSPENDED','INACTIVE')),criticality text not null default 'MEDIUM' check(criticality in('LOW','MEDIUM','HIGH','CRITICAL')),strategic boolean not null default false,internal_owner_id uuid references public.user_profiles(id) on delete set null,website text,notes text,created_at timestamptz not null default now(),created_by uuid references public.user_profiles(id) on delete set null,updated_at timestamptz not null default now(),updated_by uuid references public.user_profiles(id) on delete set null,unique(organization_id,legal_name));
create table public.supplier_contacts(id uuid primary key default gen_random_uuid(),supplier_id uuid not null references public.suppliers(id) on delete restrict,organization_id uuid not null references public.organizations(id) on delete restrict,name text not null check(length(trim(name)) between 2 and 200),contact_type text not null check(contact_type in('COMMERCIAL','SUPPORT','FINANCIAL','ACCOUNT_MANAGER','ESCALATION','EMERGENCY')),email text,phone text,priority smallint not null default 1 check(priority between 1 and 9),active boolean not null default true,created_at timestamptz not null default now(),unique(supplier_id,email));
create trigger suppliers_updated before update on public.suppliers for each row execute function public.set_updated_at();
create index suppliers_org_criticality_idx on public.suppliers(organization_id,status,criticality);
alter table public.suppliers enable row level security; alter table public.supplier_contacts enable row level security;
create policy "members read suppliers" on public.suppliers for select to authenticated using(public.is_organization_member(organization_id));
create policy "admins manage suppliers" on public.suppliers for all to authenticated using(public.has_organization_role(organization_id,array['SUPER_ADMIN','ORG_ADMIN','MANAGER']::public.platform_role[])) with check(public.has_organization_role(organization_id,array['SUPER_ADMIN','ORG_ADMIN','MANAGER']::public.platform_role[]));
create policy "members read supplier contacts" on public.supplier_contacts for select to authenticated using(public.is_organization_member(organization_id));
create policy "admins manage supplier contacts" on public.supplier_contacts for all to authenticated using(public.has_organization_role(organization_id,array['SUPER_ADMIN','ORG_ADMIN','MANAGER']::public.platform_role[])) with check(public.has_organization_role(organization_id,array['SUPER_ADMIN','ORG_ADMIN','MANAGER']::public.platform_role[]));
